import{_ as r,o,c as a,a2 as l}from"./chunks/framework.CLq81i8L.js";const u=JSON.parse('{"title":"更新日志","description":"","frontmatter":{"title":"更新日志"},"headers":[],"relativePath":"ai/changelog.md","filePath":"ai/changelog.md","lastUpdated":1785294095000}'),e={name:"ai/changelog.md"};function n(i,t,d,s,g,h){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="ai-平台-·-更新日志" tabindex="-1">AI 平台 · 更新日志 <a class="header-anchor" href="#ai-平台-·-更新日志" aria-label="Permalink to &quot;AI 平台 · 更新日志&quot;">​</a></h1><blockquote><p>记录 AI 平台（对话 Agent / Agent Workflow / RAG / 插件中心）的主要功能迭代。 内部规划文档归档于 <code>ai/product/</code>，不在此展示。</p></blockquote><h2 id="_2026-07-27-·-多智能体与长程记忆" tabindex="-1">2026-07-27 · 多智能体与长程记忆 <a class="header-anchor" href="#_2026-07-27-·-多智能体与长程记忆" aria-label="Permalink to &quot;2026-07-27 · 多智能体与长程记忆&quot;">​</a></h2><ul><li><strong>Memory 节点</strong>：工作流支持长程记忆节点，跨会话上下文持久化</li><li><strong>Agent Handoff</strong>：多专家间任务交接，显式 handoff 协议</li><li><strong>并行执行</strong>：<code>parallel</code> 节点支持多分支并行 + 汇聚</li><li><strong>Agentic RAG</strong>：检索增强从被动引用升级为主动检索决策</li></ul><h2 id="_2026-07-24-·-全链路架构与提示词优化" tabindex="-1">2026-07-24 · 全链路架构与提示词优化 <a class="header-anchor" href="#_2026-07-24-·-全链路架构与提示词优化" aria-label="Permalink to &quot;2026-07-24 · 全链路架构与提示词优化&quot;">​</a></h2><ul><li><strong>全链路架构梳理</strong>：Chat -&gt; LangGraph -&gt; LLM -&gt; 行业模板完整链路</li><li><strong>LangGraph 优化</strong>：12 项优化（状态管理、节点复用、错误恢复）</li><li><strong>提示词优化</strong>：温度策略 + 提示词规范，输出稳定性提升</li><li><strong>垂直领域分析</strong>：表单/流程 + AI 差异化场景拆解</li></ul><h2 id="_2026-07-22-·-智能体深化与-workflow-as-agent" tabindex="-1">2026-07-22 · 智能体深化与 Workflow-as-Agent <a class="header-anchor" href="#_2026-07-22-·-智能体深化与-workflow-as-agent" aria-label="Permalink to &quot;2026-07-22 · 智能体深化与 Workflow-as-Agent&quot;">​</a></h2><ul><li><strong>子 Workflow 调用</strong>：工作流节点可调用已发布的子工作流</li><li><strong>成本可见与配额</strong>：执行成本统计、租户配额管理</li><li><strong>agent-loop 节点</strong>：工作流支持自主循环决策</li><li><strong>Workflow 作技能</strong>：已发布 workflow 可作为 Agent 技能被调用</li><li><strong>复杂文件组件化</strong>：大文件拆分，首屏性能优化</li></ul><h2 id="_2026-07-20-·-开源就绪评估" tabindex="-1">2026-07-20 · 开源就绪评估 <a class="header-anchor" href="#_2026-07-20-·-开源就绪评估" aria-label="Permalink to &quot;2026-07-20 · 开源就绪评估&quot;">​</a></h2><ul><li><strong>五大能力成熟度盘点</strong>：对话/工作流/插件成熟，RAG/集成待补</li><li><strong>开源就绪度诊断</strong>：i18n、前端埋点、文档校准短板识别并立项</li><li><strong>行业模板扩充</strong>：覆盖 10 个分类（HR/财务/运营/客服/法务等）</li></ul><h2 id="_2026-07-15-·-插件中心完善" tabindex="-1">2026-07-15 · 插件中心完善 <a class="header-anchor" href="#_2026-07-15-·-插件中心完善" aria-label="Permalink to &quot;2026-07-15 · 插件中心完善&quot;">​</a></h2><ul><li><strong>插件热重载</strong>：HUP 信号触发热重载，无需重启服务</li><li><strong>Skill 拼装规范</strong>：Skill 组装技术规范定稿</li><li><strong>Pack Spec v1</strong>：插件打包规范 v1 发布</li><li><strong>第三方插件指南</strong>：外部开发者接入文档</li></ul><h2 id="_2026-07-10-·-rag-知识库" tabindex="-1">2026-07-10 · RAG 知识库 <a class="header-anchor" href="#_2026-07-10-·-rag-知识库" aria-label="Permalink to &quot;2026-07-10 · RAG 知识库&quot;">​</a></h2><ul><li><strong>BGE-M3 embedding</strong>：向量化模型接入</li><li><strong>BGE-Reranker 重排</strong>：检索结果重排序</li><li><strong>混合加权融合</strong>：向量检索 + 关键词检索加权融合</li><li><strong>文档分块策略</strong>：智能分块、重叠窗口</li></ul><h2 id="_2026-07-05-·-agent-workflow-引擎" tabindex="-1">2026-07-05 · Agent Workflow 引擎 <a class="header-anchor" href="#_2026-07-05-·-agent-workflow-引擎" aria-label="Permalink to &quot;2026-07-05 · Agent Workflow 引擎&quot;">​</a></h2><ul><li><strong>DAG 工作流编排</strong>：32 种节点类型</li><li><strong>BullMQ 执行引擎</strong>：持久化队列 + 自动重试 + 死信队列</li><li><strong>节点执行监控</strong>：实时进度推送（WebSocket）</li><li><strong>子工作流调用</strong>：支持嵌套工作流</li></ul><h2 id="_2026-06-30-·-ai-对话-agent" tabindex="-1">2026-06-30 · AI 对话 Agent <a class="header-anchor" href="#_2026-06-30-·-ai-对话-agent" aria-label="Permalink to &quot;2026-06-30 · AI 对话 Agent&quot;">​</a></h2><ul><li><strong>LangGraph 多专家对话</strong>：需求分析、任务规划、工具调用</li><li><strong>工具系统</strong>：内置工具 + 自定义工具注册</li><li><strong>流式输出</strong>：SSE 流式响应</li><li><strong>会话管理</strong>：多轮对话、上下文窗口</li></ul><h2 id="_2026-06-27-·-v1-0-2" tabindex="-1">2026-06-27 · v1.0.2 <a class="header-anchor" href="#_2026-06-27-·-v1-0-2" aria-label="Permalink to &quot;2026-06-27 · v1.0.2&quot;">​</a></h2><ul><li><code>.env.development</code> / <code>.env.production</code> 创建</li><li>本地 MongoDB + 端口 3001（开发环境）</li><li><code>.npmrc</code> 统一</li></ul><h2 id="架构基线" tabindex="-1">架构基线 <a class="header-anchor" href="#架构基线" aria-label="Permalink to &quot;架构基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td>双引擎架构</td><td>Chat LangGraph StateGraph + Workflow DAG 编排</td></tr><tr><td>插件中心</td><td>Expert / Skill / Tool / MCP 配置化，热重载</td></tr><tr><td>BullMQ 执行引擎</td><td>持久化队列 + 自动重试 + 死信队列</td></tr><tr><td>RAG 知识库</td><td>向量检索 + BGE-Reranker 重排 + 混合加权融合</td></tr><tr><td>对外集成</td><td>Workflow Open API（轮询 + 回调两种模式）</td></tr></tbody></table><h2 id="能力矩阵" tabindex="-1">能力矩阵 <a class="header-anchor" href="#能力矩阵" aria-label="Permalink to &quot;能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>AI 对话 Agent</td><td>✅ 成熟</td><td>LangGraph 多专家对话、需求分析、任务规划</td></tr><tr><td>Agent Workflow</td><td>✅ 成熟</td><td>可视化 DAG 工作流编排、32 种节点</td></tr><tr><td>插件中心</td><td>✅ 成熟</td><td>Expert/Skill/Tool/MCP 配置化</td></tr><tr><td>RAG 知识库</td><td>🔄 迭代中</td><td>向量检索 + Rerank + 混合检索</td></tr><tr><td>MCP 协议</td><td>🔄 迭代中</td><td>Model Context Protocol Server 接入</td></tr><tr><td>SDK 集成</td><td>🔄 迭代中</td><td>REST API + WebSocket + SDK</td></tr></tbody></table>',24)])])}const k=r(e,[["render",n]]);export{u as __pageData,k as default};
